mapper.select:
        /* CastSmltMapper.retrieveSmltStng */
        SELECT 
		    SMLT_ID, SMLT_MDL_SN, SMLT_NM, SMLT_TYPE, CRTR_DT, EXCN_YMD, TMNL_ID, SLF_ID, PRNT_ID, 
		    FLT_SCHDL_RSRC_ID, BAG_ALCTN_RSRC_ID, CKNCT_ALCTN_RSRC_ID, PRPT_SET_RSRC_ID, MDL_RSRC_ID, 
		    EXCN_ID, CKNCT_SRVC_HR_RSRC_ID, CHKN_TYPE_RSRC_ID, FCLTY_OPNG_TBL_DG_RSRC_ID, FCLTY_OPNG_TBL_EMI_RSRC_ID, 
		    FCLTY_OPNG_TBL_IMMI_RSRC_ID, FCLTY_OPNG_TBL_SCRTY_CNTRL_RSRC_ID, FCLTY_OPNG_TBL_TR_SCRTY_CNTRL_RSRC_ID, 
		    SBD_CNTRL_ALCTN_ID, PLAN_BGNG_DT, PLAN_END_DT, SMLT_BGNG_DT, SMLT_END_DT, BDPSG_ANCE_YN
		FROM PMOWN.TN_PM_SMLT_STNG
		WHERE 1 = 1

    		AND SMLT_ID = #{smltId} 


	       	AND EXCN_YMD = #{excnYmd}


            AND SMLT_TYPE = #{smltType}

/* CastSmltMapper.retrieveXovisRsltDtl */ SELECT SUBSTR(A.PSG_FLOW_DATA_CRT_DT, 9, 4) TIME, A.TMNL_ID, A.CHKN_ISL_CD, A.FCLT_NM, A.FCLT_TYPE_CD, A.WTNG_LINE_LEN as WTNG_PSG_CNT FROM PMOWN.TN_PM_PSG_WTNG_INFO A WHERE PSG_FLOW_DATA_CRT_DT LIKE #{dt} || '%' AND A.TMNL_ID = #{tmnlId} -- Queue 체크인카운터 줄, DG 출국장, SC 보안검색대 AND A.FCLT_TYPE_CD IN (#{item}) AND A.WTNG_LINE_LEN > 0
AND A.CHKN_ISL_CD = #{island}
ORDER BY TIME
